  lines.push(`selection-background = ${tokenMap.selectionBg}`);
  lines.push(`selection-foreground = ${tokenMap.selectionFg}`);

  writeFile(`platforms/ghostty/karasu-${variant}`, `${lines.join("\n")}\n`);
}

